// Which outcomes of an event option apply to the party. An option on the card back has several outcomes, some with a
// requirement ("if a character has the Persuasive trait ...") and usually an "otherwise" at the end. This checks the
// requirements that can be checked from the record and leaves the rest for the players. Pure functions.
//
// Outcome fields (generated by tools/extract-event-text.py): t, ta, rp, o, c, n, e. See that file for their meaning.
import { CLASS_TRAITS } from '../games/gh2_class_traits.js';

const lc = v => String(v).toLowerCase();

// Reputation factions of the card data -> record keys.
const FACTION = { demons: 'demons', 'merchant-guild': 'merchants', military: 'guard' };

// Traits of one character: the traits on the sheet, plus the class's own traits and species (orchid, vermling, ...).
export function characterTraits(c) {
  const set = new Set((c.traits || []).map(lc));
  for (const t of CLASS_TRAITS[lc(c.cls || '')] || []) set.add(t);
  return set;
}

// Characters of the party with their traits: [{ name, traits: Set }]
export const partyOf = r => (r.chars || []).map(c => ({ name: c.name, traits: characterTraits(c) }));

// Is the requirement of one outcome met? Returns { ok, who } for a requirement that can be checked
// (who = names of the characters that meet it), or null when the outcome has no requirement the app can check.
export function checkRequirement(o, r) {
  const party = partyOf(r);
  if (o.t) {
    const who = party.filter(p => o.t.some(t => p.traits.has(t))).map(p => p.name);
    return { ok: who.length > 0, who };
  }
  if (o.ta) {
    const ok = party.length > 0 && party.every(p => o.ta.every(t => p.traits.has(t)));
    return { ok, who: ok ? party.map(p => p.name) : [] };
  }
  if (o.rp && FACTION[o.rp[0]]) {
    const value = r.rep?.[FACTION[o.rp[0]]];
    return { ok: typeof value === 'number' && value > o.rp[1], who: [] };
  }
  return null;
}

/*
Outcomes of an option that apply, in card order: [{ o: outcome, state, who }].
  state 'always'     no requirement
        'met'        a requirement that is met (who = characters meeting it)
        'otherwise'  the "otherwise" outcome: no requirement before it was met
        'manual'     a requirement the app cannot check (a choice, a payment, an earlier answer): the players decide
Outcomes whose checked requirement is not met are left out. An "otherwise" after an unchecked requirement is 'manual' too.
*/
export function applicableOutcomes(outcomes, r) {
  const out = [];
  let matched = false, manualSeen = false;
  for (const o of outcomes || []) {
    if (o.o) {
      if (manualSeen) out.push({ o, state: 'manual', who: [] });
      else if (!matched) out.push({ o, state: 'otherwise', who: [] });
    } else if (o.t || o.ta || (o.rp && FACTION[o.rp[0]])) {
      const res = checkRequirement(o, r);
      if (res.ok) { matched = true; out.push({ o, state: 'met', who: res.who }); }
    } else if (o.c) {
      manualSeen = true;
      out.push({ o, state: 'manual', who: [] });
    } else {
      out.push({ o, state: 'always', who: [] });
    }
  }
  return out;
}
